import os
from dotenv import load_dotenv
from app.services.stt import STTService  # Assuming the previous code is saved as stt_service.py


def test_stt_service(base64_audio: str):
    """
    Test the STT service with provided base64 audio string.
    
    Args:
        base64_audio (str): Base64 encoded audio string
    
    Returns:
        str: Transcribed text if successful
    """
    try:
        print("Initializing STT Service...")
        stt_service = STTService()
        
        print(f"Received base64 audio of length: {len(base64_audio)}")
        
        print("\nAttempting transcription...")
        transcript = stt_service.transcribe_audio(base64_audio)
        
        print("\nTest Results:")
        print("-" * 50)
        print(f"Transcription successful: {bool(transcript)}")
        print(f"Transcript content: {transcript}")
        print("-" * 50)
        
        return transcript
        
    except Exception as e:
        print("\nTranscription Failed!")
        print("-" * 50)
        print(f"Error: {str(e)}")
        print("-" * 50)
        return None

if __name__ == "__main__":
    load_dotenv(".env")
    
    # Example usage
    print("Starting STT Service Test")
    print("=" * 50)
    
    # Replace this with your actual base64 string
    sample_base64 = """"
    "
    """
    result = test_stt_service(sample_base64)
    
    print("\nTest Summary:")
    print("=" * 50)
    print(f"Test {'Passed' if result else 'Failed'}")